const prose = document.getElementById('prose-acronyms');
const bareAbbr = document.getElementById('bare-abbr');
const customAbbr = document.getElementById('custom-abbr');
const specPricing = document.getElementById('spec-pricing');
const specCharging = document.getElementById('spec-charging');
const specWireless = document.getElementById('spec-wireless');
if (!prose || !bareAbbr || !customAbbr || !specPricing || !specCharging || !specWireless) return false;

const isEnabled = document.getElementById('ai4a11y-abbr-styles') !== null;
if (!isEnabled) {
  // Before enable: no ai4a11y-abbr elements, bareAbbr has no title
  return document.querySelectorAll('.ai4a11y-abbr').length === 0 &&
         !bareAbbr.hasAttribute('title') &&
         customAbbr.getAttribute('title') === 'Custom Federal Agency Title';
}

// After enable: check that acronyms are wrapped with correct titles
const proseAbbrs = [...prose.querySelectorAll('abbr.ai4a11y-abbr')];
const hasWCAG = proseAbbrs.some(a => a.textContent === 'WCAG' && a.title === 'Web Content Accessibility Guidelines');
const hasHTML = proseAbbrs.some(a => a.textContent === 'HTML' && a.title === 'HyperText Markup Language');
const hasCSS = proseAbbrs.some(a => a.textContent === 'CSS' && a.title === 'Cascading Style Sheets');
const hasHTTPS = proseAbbrs.some(a => a.textContent === 'HTTPS' && a.title === 'HyperText Transfer Protocol Secure');
const hasAPI = proseAbbrs.some(a => a.textContent === 'API' && a.title === 'Application Programming Interface');
const hasJSON = proseAbbrs.some(a => a.textContent === 'JSON' && a.title === 'JavaScript Object Notation');
if (!hasWCAG || !hasHTML || !hasCSS || !hasHTTPS || !hasAPI || !hasJSON) return false;

// Check specs section
const pricingAbbrs = [...specPricing.querySelectorAll('abbr.ai4a11y-abbr')];
const hasMSRP = pricingAbbrs.some(a => a.textContent === 'MSRP' && a.title.includes('suggested retail price'));
const hasQty = pricingAbbrs.some(a => a.textContent === 'Qty' && a.title === 'quantity');
if (!hasMSRP || !hasQty) return false;

const chargingAbbrs = [...specCharging.querySelectorAll('abbr.ai4a11y-abbr')];
const hasGaN = chargingAbbrs.some(a => a.textContent === 'GaN' && a.title.includes('gallium nitride'));
const hasUSB = chargingAbbrs.some(a => a.textContent === 'USB' && a.title === 'Universal Serial Bus');
const hasPD = chargingAbbrs.some(a => a.textContent === 'PD' && a.title.includes('Power Delivery'));
if (!hasGaN || !hasUSB || !hasPD) return false;

const wirelessAbbrs = [...specWireless.querySelectorAll('abbr.ai4a11y-abbr')];
const hasBT = wirelessAbbrs.some(a => a.textContent === 'BT' && a.title === 'Bluetooth');
const hasANC = wirelessAbbrs.some(a => a.textContent === 'ANC' && a.title === 'active noise cancellation');
if (!hasBT || !hasANC) return false;

// Check pre-existing abbr tags
if (bareAbbr.getAttribute('title') !== 'National Aeronautics and Space Administration') return false;
if (customAbbr.getAttribute('title') !== 'Custom Federal Agency Title') return false;

// Check styling
const anyAbbr = proseAbbrs[0];
const cs = window.getComputedStyle(anyAbbr);
if (cs.cursor !== 'help' || !cs.textDecorationLine.includes('underline')) return false;

return true;

const codeSnippet = document.getElementById('code-snippet');
const searchInput = document.getElementById('search-box');
const liveStatus = document.getElementById('live-announcement');
const partialMatches = document.getElementById('partial-matches');
const plainText = document.getElementById('plain-text');
if (!codeSnippet || !searchInput || !liveStatus || !partialMatches || !plainText) return false;

// Inside CODE / PRE: must not have any abbr wrappers
if (codeSnippet.querySelectorAll('abbr').length !== 0) return false;

// Inside form inputs: no abbr
if (searchInput.value !== 'WCAG and HTML compliance tips') return false;

// Inside live region: must not wrap text so screen reader is not triggered
if (liveStatus.querySelectorAll('abbr').length !== 0) return false;

// Partial words: "APIs", "SCRAPI", lowercase "ram" must not match
if (partialMatches.querySelectorAll('abbr').length !== 0) return false;
if (!partialMatches.textContent.includes('APIs and SCRAPI systems')) return false;

// Plain text: no abbr
if (plainText.querySelectorAll('abbr').length !== 0) return false;

return true;

const container = document.getElementById('dynamic-container');
if (!container) return false;

const isEnabled = document.getElementById('ai4a11y-abbr-styles') !== null;
if (!isEnabled) return true;

// Add dynamic content
const p = document.createElement('p');
p.id = 'dynamic-test-p';
p.textContent = 'Modern systems require powerful GPU and RAM hardware.';
const bare = document.createElement('abbr');
bare.id = 'dynamic-test-abbr';
bare.textContent = 'CPU';
container.appendChild(p);
container.appendChild(bare);

// Wait for observer rescan (400ms delay + buffer)
await new Promise(r => setTimeout(r, 500));

const abbrs = [...p.querySelectorAll('abbr.ai4a11y-abbr')];
const hasGPU = abbrs.some(a => a.textContent === 'GPU' && a.title === 'Graphics Processing Unit');
const hasRAM = abbrs.some(a => a.textContent === 'RAM' && a.title === 'Random Access Memory');
const cpuTitle = bare.getAttribute('title');

// Put the page back exactly as it was
p.remove();
bare.remove();

return hasGPU && hasRAM && cpuTitle === 'Central Processing Unit';

const prose = document.getElementById('prose-acronyms');
if (!prose) return false;

const expectedText = 'Our team adheres to the WCAG guidelines to build accessible HTML and CSS user interfaces. Each client connects through a secure HTTPS API endpoint to retrieve data formatted in JSON.';
// Normalize whitespace
const currentText = prose.textContent.replace(/\s+/g, ' ').trim();
if (currentText !== expectedText) return false;

// Abbr elements should not introduce unexpected interactive tab stops into ordinary prose
const proseAbbrs = prose.querySelectorAll('abbr');
for (const a of proseAbbrs) {
  if (a.hasAttribute('tabindex') && a.tabIndex >= 0) return false;
}

return true;
